import numpy as np

def compute_log_spectrum(gray: np.ndarray) -> np.ndarray:
    f_shift = np.fft.fftshift(np.fft.fft2(gray.astype(np.float64)))
    mag = np.log1p(np.abs(f_shift))
    mag_norm = (mag / max(1e-8, np.max(mag))) * 255.0
    return np.clip(np.round(mag_norm), 0, 255).astype(np.uint8)
